import React, { useState, useEffect } from 'react';
import { toast } from 'react-toastify';
import { FiPlus, FiTrash2, FiEdit2 } from 'react-icons/fi';
import api from '../../services/api';
import AdminModal from '../common/AdminModal';
import AdminCard from '../common/AdminCard';

const AdminGallery = () => {
  const [images, setImages] = useState([]);
  const [loading, setLoading] = useState(true);
  const [modalOpen, setModalOpen] = useState(false);
  const [editingImage, setEditingImage] = useState(null);
  const [formData, setFormData] = useState({
    title: '',
    category: '',
    image_url: '',
    description: '',
    is_featured: false,
    order: 0,
  });

  const categories = ['School Activities', 'Classroom', 'Graduation', 'Trips', 'Special Events'];

  useEffect(() => {
    fetchImages();
  }, []);

  const fetchImages = async () => {
    try {
      const response = await api.get('/api/gallery/');
      setImages(response.data);
    } catch (error) {
      toast.error('Failed to load gallery');
    } finally {
      setLoading(false);
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    try {
      if (editingImage) {
        await api.put(`/api/gallery/${editingImage.id}`, formData);
        toast.success('Image updated successfully');
      } else {
        await api.post('/api/gallery/', formData);
        toast.success('Image added successfully');
      }
      setModalOpen(false);
      setEditingImage(null);
      setFormData({
        title: '',
        category: '',
        image_url: '',
        description: '',
        is_featured: false,
        order: 0,
      });
      fetchImages();
    } catch (error) {
      toast.error(error.response?.data?.detail || 'Operation failed');
    }
  };

  const handleDelete = async (id) => {
    if (window.confirm('Are you sure you want to delete this image?')) {
      try {
        await api.delete(`/api/gallery/${id}`);
        toast.success('Image deleted successfully');
        fetchImages();
      } catch (error) {
        toast.error('Failed to delete image');
      }
    }
  };

  const handleEdit = (image) => {
    setEditingImage(image);
    setFormData({
      title: image.title || '',
      category: image.category || '',
      image_url: image.image_url,
      description: image.description || '',
      is_featured: image.is_featured,
      order: image.order || 0,
    });
    setModalOpen(true);
  };

  return (
    <div>
      <div className="flex justify-between items-center mb-6">
        <h1 className="text-3xl font-bold text-blue-900">Gallery Management</h1>
        <button
          onClick={() => {
            setEditingImage(null);
            setFormData({
              title: '',
              category: '',
              image_url: '',
              description: '',
              is_featured: false,
              order: 0,
            });
            setModalOpen(true);
          }}
          className="admin-btn-primary flex items-center space-x-2"
        >
          <FiPlus />
          <span>Add Image</span>
        </button>
      </div>

      {loading ? (
        <div className="flex justify-center py-12">
          <div className="animate-spin rounded-full h-12 w-12 border-t-2 border-b-2 border-blue-900"></div>
        </div>
      ) : (
        <div className="grid grid-cols-1 md:grid-cols-3 lg:grid-cols-4 gap-4">
          {images.map((image) => (
            <AdminCard key={image.id} className="overflow-hidden">
              <img
                src={image.image_url}
                alt={image.title || 'Gallery'}
                className="w-full h-48 object-cover"
                onError={(e) => {
                  e.target.src = 'https://via.placeholder.com/300x200?text=No+Image';
                }}
              />
              <div className="p-4">
                <h3 className="font-semibold text-blue-900 truncate">
                  {image.title || 'Untitled'}
                </h3>
                {image.category && (
                  <p className="text-sm text-gray-500">{image.category}</p>
                )}
                <div className="flex justify-end space-x-2 mt-2">
                  <button
                    onClick={() => handleEdit(image)}
                    className="text-blue-600 hover:text-blue-800"
                  >
                    <FiEdit2 />
                  </button>
                  <button
                    onClick={() => handleDelete(image.id)}
                    className="text-red-600 hover:text-red-800"
                  >
                    <FiTrash2 />
                  </button>
                </div>
              </div>
            </AdminCard>
          ))}
        </div>
      )}

      <AdminModal
        isOpen={modalOpen}
        onClose={() => {
          setModalOpen(false);
          setEditingImage(null);
        }}
        title={editingImage ? 'Edit Image' : 'Add Image'}
      >
        <form onSubmit={handleSubmit}>
          <div className="space-y-4">
            <div>
              <label className="admin-label">Title</label>
              <input
                type="text"
                value={formData.title}
                onChange={(e) => setFormData({ ...formData, title: e.target.value })}
                className="admin-input"
              />
            </div>
            <div>
              <label className="admin-label">Category</label>
              <select
                value={formData.category}
                onChange={(e) => setFormData({ ...formData, category: e.target.value })}
                className="admin-input"
              >
                <option value="">Select Category</option>
                {categories.map((cat) => (
                  <option key={cat} value={cat}>{cat}</option>
                ))}
              </select>
            </div>
            <div>
              <label className="admin-label">Image URL *</label>
              <input
                type="text"
                value={formData.image_url}
                onChange={(e) => setFormData({ ...formData, image_url: e.target.value })}
                className="admin-input"
                required
                placeholder="https://example.com/image.jpg"
              />
            </div>
            <div>
              <label className="admin-label">Description</label>
              <textarea
                value={formData.description}
                onChange={(e) => setFormData({ ...formData, description: e.target.value })}
                className="admin-input"
                rows="2"
              />
            </div>
            <div className="flex space-x-4">
              <label className="flex items-center space-x-2">
                <input
                  type="checkbox"
                  checked={formData.is_featured}
                  onChange={(e) => setFormData({ ...formData, is_featured: e.target.checked })}
                />
                <span>Featured</span>
              </label>
            </div>
          </div>
          <div className="mt-6 flex justify-end space-x-3">
            <button
              type="button"
              onClick={() => {
                setModalOpen(false);
                setEditingImage(null);
              }}
              className="admin-btn-secondary"
            >
              Cancel
            </button>
            <button type="submit" className="admin-btn-primary">
              {editingImage ? 'Update' : 'Add'}
            </button>
          </div>
        </form>
      </AdminModal>
    </div>
  );
};

export default AdminGallery;
